
-- 1. Enable Vector Extension
CREATE EXTENSION IF NOT EXISTS vector;

-- 2. Create Standards Table
CREATE TABLE IF NOT EXISTS standards (
  standard_id text PRIMARY KEY,
  title text NOT NULL,
  scope text,
  embedding vector(768),
  latest_version text,
  amendment_date text,
  is_mandatory_qco boolean DEFAULT false
);

-- 3. Create Standard References Table
CREATE TABLE IF NOT EXISTS standard_references (
  standard_id text REFERENCES standards(standard_id),
  referenced_id text,
  referenced_title text,
  relationship_type text,
  PRIMARY KEY (standard_id, referenced_id)
);

-- 4. Create Vector Match Function
CREATE OR REPLACE FUNCTION match_standards(query_embedding vector(768), match_count int)
RETURNS TABLE (standard_id text, title text, similarity float)
LANGUAGE sql STABLE
AS $$
  SELECT standard_id, title, 1 - (embedding <=> query_embedding) AS similarity
  FROM standards
  ORDER BY embedding <=> query_embedding
  LIMIT match_count;
$$;

-- 5. Disable RLS to allow direct access
ALTER TABLE standards DISABLE ROW LEVEL SECURITY;
ALTER TABLE standard_references DISABLE ROW LEVEL SECURITY;

-- 6. Clear existing data if re-running
TRUNCATE TABLE standard_references CASCADE;
TRUNCATE TABLE standards CASCADE;

-- 7. Insert Master Standards with Pre-computed 768-dim Embeddings
